    q.memset(d_out, 0, sizeof(float) * NV).wait();
    softmax_forward(q, k, d_out, d_inp, static_cast<int>(N), V);
    q.memcpy(out, d_out, sizeof(float) * NV).wait();
    std::fwrite(out, sizeof(float), NV, fout);
  }
  std::fclose(fout);
  sycl::free(d_inp, q);
  sycl::free(d_out, q);
  std::free(inp);
  std::free(outliers);
  std::free(out);
  return 0;
}

